import type { SubjectId } from './data';
import type { QuizQuestion } from './types';

const AT = '2026-01-01T00:00:00.000Z';
let index = 0;
/**
 * Third depth pass: brings every chapter up to at least ten banked questions so a
 * ten-question chapter test is always a real paper, not a four-question one.
 *
 * Same rules as before: textbook facts only, four distinct options, an explanation
 * that says why. Ids stay in their own `more-` range so stored attempts never shift.
 */
function q(subject: SubjectId, chapterId: string, question: string, options: string[], answer: number, explanation: string): QuizQuestion {
  index += 1;
  return {
    id: `more-${String(index).padStart(3, '0')}`, subject, chapterId, question, options, answer,
    explanation, source: 'গভীরতা ব্যাংক · পাঠ্যবইয়ের তথ্য', createdAt: AT, bank: true,
  };
}

